    H: '<rect width="15" height="20" fill="#fff"/><rect x="15" width="15" height="20" fill="#dc2626"/>',
    I: '<rect width="30" height="20" fill="#facc15"/><circle cx="15" cy="10" r="5.5" fill="#000"/>',
