    K: '<rect width="15" height="20" fill="#facc15"/><rect x="15" width="15" height="20" fill="#1e40af"/>',
    L: '<rect width="30" height="20" fill="#000"/><rect width="15" height="10" fill="#facc15"/><rect x="15" y="10" width="15" height="10" fill="#facc15"/>',
